1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	};
5	
6	export type Step =
7	  | { op: "quote"; items: Item[] }
8	  | { op: "claim"; policy: number; incident: Incident };
9	
10	export type Item = {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type Damage = {
23	  itemType: string;
24	  amount: number;
25	};
26	
27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
31	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	  moonstone: 25,
38	};
39	
40	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_BASE_PREMIUM = 60;
44	
45	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
46	  alikeItems.length === BLOCK_SIZE;
47	
48	const sumOfBasePremiums = (items: Item[]): number =>
49	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
50	
51	const groupedByType = (items: Item[]): Item[][] => {
52	  const groups = new Map<string, Item[]>();
53	  for (const item of items) {
54	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
55	  }
56	  return [...groups.values()];
57	};
58	
59	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
60	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
61	
62	const policyBaseOf = (items: Item[]): number =>
63	  groupedByType(items).reduce((sum, group) => sum + basePremiumOfAlikeItems(group), 0);
64	
65	// Rounding always favours the MHPCO: premiums up, payouts down.
66	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
67	
68	const firstInsuranceSurchargeOn = (policyBase: number): number =>
69	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
70	
71	const quoteFor = (items: Item[]): Result => {
72	  const policyBase = policyBaseOf(items);
73	  return {
74	    premium: premiumRoundedInMHPCOsFavour(
75	      policyBase + firstInsuranceSurchargeOn(policyBase) + PROCESSING_FEE,
76	    ),
77	  };
78	};
79	
80	const resultFor = (step: Step): Result => {
81	  if (step.op === "quote") return quoteFor(step.items);
82	  throw new Error(`unsupported step: ${step.op}`);
83	};
84	
85	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
86	  results: scenario.steps.map(resultFor),
87	});
